export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  var scene = new BABYLON.Scene(engine);
  scene.clearColor = BABYLON.Color4.FromHexString("#636363FF");

  var camera = new BABYLON.FreeCamera("camera1", new BABYLON.Vector3(0, 2, -5), scene);
  camera.setTarget(new BABYLON.Vector3(-0.19, 65.97, -16.84));
  camera.position = new BABYLON.Vector3(-0.19, 71.35, -16.84);
  camera.rotation = new BABYLON.Vector3(Math.PI / 2, 0, 0);
  camera.inertia = 0.2;
  camera.minZ = 0.01;
  camera.attachControl(canvas, true);

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.8;

  var targetSize = 0.5;
  var target = BABYLON.MeshBuilder.CreateBox("target", { size: targetSize }, scene);
  target.setPivotPoint(new BABYLON.Vector3(0, -targetSize / 2, 0), BABYLON.Space.LOCAL);
  target.position.y = targetSize * 3.5;
  target.setEnabled(false);

  let rootMesh;

  BABYLON.SceneLoader.ImportMeshAsync("", "https://playgrounds.babylonjs.xyz/", "B0004.T0000003.1.glb").then((result) => {
    rootMesh = result.meshes[0];
    const mat = createCustomWindowGlassMaterial("myMat");

    scene.meshes.forEach((m) => {
      if (isFromMaterial(m, "Glass")) {
        m.alphaIndex = 2;
        m.material = mat;
      }
    });

    function createCustomWindowGlassMaterial(name) {
      const glassMaterial = new BABYLON.PBRMaterial(name, scene);
      glassMaterial.emissiveColor = new BABYLON.Color3(0.415, 0.549, 0.588);
      glassMaterial.alpha = 0.8;
      glassMaterial.transparencyMode = BABYLON.Material.MATERIAL_ALPHABLEND;
      glassMaterial.alphaMode = BABYLON.Engine.ALPHA_MULTIPLY;
      glassMaterial.backFaceCulling = false;
      glassMaterial.needDepthPrePass = true;
      return glassMaterial;
    }

    function isFromMaterial(m, materialName) {
      return (
        m.material &&
        (m.material.name === materialName || m.material.name.startsWith(materialName + ".") || m.material.name.startsWith(materialName + "_"))
      );
    }
  });

  scene.onPointerDown = function (evt) {
    if (evt.button === 2) {
      var pickedPoint = pickPoint(evt);
      if (pickedPoint) {
        target.position = pickedPoint;
        camera.position = target.position.clone().add(new BABYLON.Vector3(0, targetSize * 3.5, 0));
      }
    }
  };

  function pickPoint(event) {
    var pickResult = scene.pick(scene.pointerX, scene.pointerY);
    if (pickResult.hit) {
      return pickResult.pickedPoint;
    }
  }

  var size = 2048;

  var skybox = BABYLON.MeshBuilder.CreateBox("skyBox", { size: 1000.0 }, scene);
  var skyboxMaterial = new BABYLON.StandardMaterial("skyBox", scene);
  skyboxMaterial.backFaceCulling = false;
  skyboxMaterial.disableLighting = true;
  skybox.material = skyboxMaterial;
  skybox.visibility = 0;

  var advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

  var button = BABYLON.GUI.Button.CreateSimpleButton("screenshotBtn", "📷");
  button.width = "60px";
  button.height = "60px";
  button.color = "white";
  button.background = "black";
  button.cornerRadius = 30;
  button.thickness = 0;
  button.alpha = 0.6;
  button.top = "-10px";
  button.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_BOTTOM;
  advancedTexture.addControl(button);

  const panel = new BABYLON.GUI.StackPanel();
  panel.width = "600px";
  panel.isVertical = true;
  panel.adaptHeightToChildren = true;
  panel.spacing = 4;
  panel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  panel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  panel.paddingTop = "10px";
  panel.paddingLeft = "10px";
  advancedTexture.addControl(panel);

  function createOutlinedText(text) {
    const t = new BABYLON.GUI.TextBlock();
    t.text = text;
    t.color = "white";
    t.outlineColor = "black";
    t.outlineWidth = 4;
    t.fontSize = 18;
    t.height = "28px";
    t.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    t.textVerticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
    return t;
  }

  const lines = [
    "1. Move the camera with arrow keys (↑, ←, ↓, →)",
    "2. Set the camera with the right mouse click",
    "3. Click the camera button below when you're ready",
    "4. Then, boom! You’ve got the Skybox 🎉",
  ];

  lines.forEach((line) => panel.addControl(createOutlinedText(line)));

  var directions = [
    { target: new BABYLON.Vector3(1, 0, 0), up: new BABYLON.Vector3(0, 1, 0) }, // +X
    { target: new BABYLON.Vector3(-1, 0, 0), up: new BABYLON.Vector3(0, 0, -1) }, // -X
    { target: new BABYLON.Vector3(0, 1, 0), up: new BABYLON.Vector3(0, 1, 0) }, // +Y
    { target: new BABYLON.Vector3(0, -1, 0), up: new BABYLON.Vector3(0, 0, 1) }, // -Y
    { target: new BABYLON.Vector3(0, 0, 1), up: new BABYLON.Vector3(0, 1, 0) }, // +Z
    { target: new BABYLON.Vector3(0, 0, -1), up: new BABYLON.Vector3(0, 1, 0) }, // -Z
  ];

  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  async function capture360() {
    advancedTexture.rootContainer.isVisible = false;
    target.setEnabled(false);

    var pos = camera.position.clone();
    var urls = [];
    var names = ["px", "nx", "py", "ny", "pz", "nz"];

    for (let i = 0; i < directions.length; i++) {
      let dir = directions[i];

      var tempCam = new BABYLON.FreeCamera("tempCam", pos.clone(), scene);
      tempCam.mode = BABYLON.Camera.PERSPECTIVE_CAMERA;
      tempCam.fov = Math.PI / 2;
      tempCam.minZ = 0.01;

      tempCam.setTarget(pos.add(dir.target));
      if (i === 2) {
        tempCam.rotation.z += Math.PI;
      }

      camera.setTarget(pos.add(dir.target));

      await sleep(500);

      let data = await BABYLON.Tools.CreateScreenshotAsync(engine, tempCam, size);

      let link = document.createElement("a");
      link.href = data;
      link.download = names[i] + ".png";
      document.body.appendChild(link);
      //   link.click();
      document.body.removeChild(link);

      urls.push(data);
      tempCam.dispose();
    }

    // [ +X, -X, +Y, -Y, +Z, -Z ]
    let skyboxUrls = [
      urls[0], // +X
      urls[2], // -X
      urls[4], // +Y
      urls[1], // -Y
      urls[3], // +Z
      urls[5], // -Z
    ];

    var cubeTex = BABYLON.CubeTexture.CreateFromImages(skyboxUrls, scene, false);
    skyboxMaterial.reflectionTexture = cubeTex;
    skyboxMaterial.reflectionTexture.coordinatesMode = BABYLON.Texture.SKYBOX_MODE;

    advancedTexture.rootContainer.isVisible = true;
    skybox.visibility = 1;

    scene.meshes
      .filter((m) => m !== skybox)
      .forEach((m) => {
        m.setEnabled(false);
      });

    createDirectionLabels();
  }

  button.onPointerClickObservable.add(capture360);

  function createDirectionLabels() {
    const planeSize = 3;
    const offset = 25;

    const directions = [
      { name: "px", position: new BABYLON.Vector3(offset, 0, 0), rotation: new BABYLON.Vector3(0, Math.PI / 2, 0) },
      { name: "nx", position: new BABYLON.Vector3(-offset, 0, 0), rotation: new BABYLON.Vector3(0, -Math.PI / 2, 0) },
      { name: "py", position: new BABYLON.Vector3(0, offset, 0), rotation: new BABYLON.Vector3(-Math.PI / 2, 0, 0) },
      { name: "ny", position: new BABYLON.Vector3(0, -offset, 0), rotation: new BABYLON.Vector3(Math.PI / 2, 0, 0) },
      { name: "pz", position: new BABYLON.Vector3(0, 0, offset), rotation: new BABYLON.Vector3(0, 0, 0) },
      { name: "nz", position: new BABYLON.Vector3(0, 0, -offset), rotation: new BABYLON.Vector3(0, Math.PI, 0) },
    ];

    directions.forEach((dir) => {
      const plane = BABYLON.MeshBuilder.CreatePlane("label_" + dir.name, { size: planeSize }, scene);
      plane.position = camera.position.add(dir.position);
      plane.rotation = dir.rotation;

      const dynamicTexture = new BABYLON.DynamicTexture("dt_" + dir.name, { width: 512, height: 256 }, scene, false);
      dynamicTexture.hasAlpha = true;

      const ctx = dynamicTexture.getContext();
      ctx.font = "bold 120px Arial";
      ctx.fillStyle = "white";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.clearRect(0, 0, 512, 256);
      ctx.fillText(dir.name.toUpperCase(), 256, 128);
      dynamicTexture.update();

      const mat = new BABYLON.StandardMaterial("mat_" + dir.name, scene);
      mat.diffuseTexture = dynamicTexture;
      mat.emissiveColor = BABYLON.Color3.White();
      mat.backFaceCulling = false;
      plane.material = mat;
    });
  }

  return scene;
}
